solution.markdown.zig:
const std = @import("std");

// Refactoring separates line structure from inline emphasis and list state.
fn inlineText(out: *std.array_list.Managed(u8), text: []const u8) anyerror!void {
    var i: usize = 0;
    while (i < text.len) {
        if (text[i] == '_') {
            const count: usize = if (i + 1 < text.len and text[i + 1] == '_') 2 else 1;
            const marker = if (count == 2) "__" else "_";
            if (std.mem.indexOf(u8, text[i + count ..], marker)) |offset| {
                const tag = if (count == 2) "strong" else "em";
                try out.append('<');
                try out.appendSlice(tag);
                try out.append('>');
                try inlineText(out, text[i + count .. i + count + offset]);
                try out.appendSlice("</");
                try out.appendSlice(tag);
                try out.append('>');
                i += count + offset + count;
                continue;
            }
        }
        try out.append(text[i]);
        i += 1;
    }
}
pub fn parse(allocator: std.mem.Allocator, markdown: []const u8) ![]u8 {
    var out = std.array_list.Managed(u8).init(allocator);
    errdefer out.deinit();
    var lines = std.mem.splitScalar(u8, markdown, '\n');
    var in_list = false;
    while (lines.next()) |line| {
        const list_item = std.mem.startsWith(u8, line, "* ");
        if (in_list and !list_item) {
            try out.appendSlice("</ul>");
            in_list = false;
        }
        if (list_item) {
            if (!in_list) {
                try out.appendSlice("<ul>");
                in_list = true;
            }
            try out.appendSlice("<li>");
            try inlineText(&out, line[2..]);
            try out.appendSlice("</li>");
            continue;
        }
        var level: usize = 0;
        while (level < line.len and line[level] == '#') : (level += 1) {}
        if (level >= 1 and level <= 6 and level < line.len and line[level] == ' ') {
            try out.appendSlice("<h");
            try out.append(@as(u8, @intCast(level)) + '0');
            try out.append('>');
            try inlineText(&out, line[level + 1 ..]);
            try out.appendSlice("</h");
            try out.append(@as(u8, @intCast(level)) + '0');
            try out.append('>');
        } else {
            try out.appendSlice("<p>");
            try inlineText(&out, line);
            try out.appendSlice("</p>");
        }
    }
    if (in_list) try out.appendSlice("</ul>");
    return out.toOwnedSlice();
}

tests.test_markdown.zig:
const std = @import("std");
const t = std.testing;
const a = t.allocator;
const m = @import("markdown.zig");
test "test_parses_normal_text_as_a_paragraph" {
    const out = try m.parse(a, "This will be a paragraph");
    defer a.free(out);
    try t.expectEqualStrings("<p>This will be a paragraph</p>", out);
}
test "test_parsing_italics" {
    const out = try m.parse(a, "_This will be italic_");
    defer a.free(out);
    try t.expectEqualStrings("<p><em>This will be italic</em></p>", out);
}
test "test_parsing_bold_text" {
    const out = try m.parse(a, "__This will be bold__");
    defer a.free(out);
    try t.expectEqualStrings("<p><strong>This will be bold</strong></p>", out);
}
test "test_mixed_normal_italics_and_bold_text" {
    const out = try m.parse(a, "This will _be_ __mixed__");
    defer a.free(out);
    try t.expectEqualStrings("<p>This will <em>be</em> <strong>mixed</strong></p>", out);
}
test "test_with_h1_header_level" {
    const out = try m.parse(a, "# This will be an h1");
    defer a.free(out);
    try t.expectEqualStrings("<h1>This will be an h1</h1>", out);
}
test "test_with_h2_header_level" {
    const out = try m.parse(a, "## This will be an h2");
    defer a.free(out);
    try t.expectEqualStrings("<h2>This will be an h2</h2>", out);
}
test "test_with_h3_header_level" {
    const out = try m.parse(a, "### This will be an h3");
    defer a.free(out);
    try t.expectEqualStrings("<h3>This will be an h3</h3>", out);
}
test "test_with_h4_header_level" {
    const out = try m.parse(a, "#### This will be an h4");
    defer a.free(out);
    try t.expectEqualStrings("<h4>This will be an h4</h4>", out);
}
test "test_with_h5_header_level" {
    const out = try m.parse(a, "##### This will be an h5");
    defer a.free(out);
    try t.expectEqualStrings("<h5>This will be an h5</h5>", out);
}
test "test_with_h6_header_level" {
    const out = try m.parse(a, "###### This will be an h6");
    defer a.free(out);
    try t.expectEqualStrings("<h6>This will be an h6</h6>", out);
}
test "test_h7_header_level_is_a_paragraph" {
    const out = try m.parse(a, "####### This will not be an h7");
    defer a.free(out);
    try t.expectEqualStrings("<p>####### This will not be an h7</p>", out);
}
test "test_unordered_lists" {
    const out = try m.parse(a, "* Item 1\n* Item 2");
    defer a.free(out);
    try t.expectEqualStrings("<ul><li>Item 1</li><li>Item 2</li></ul>", out);
}
test "test_with_a_little_bit_of_everything" {
    const out = try m.parse(a, "# Header!\n* __Bold Item__\n* _Italic Item_");
    defer a.free(out);
    try t.expectEqualStrings("<h1>Header!</h1><ul><li><strong>Bold Item</strong></li><li><em>Italic Item</em></li></ul>", out);
}
test "test_with_markdown_symbols_in_the_header_text_that_should_not_be_interpreted" {
    const out = try m.parse(a, "# This is a header with # and * in the text");
    defer a.free(out);
    try t.expectEqualStrings("<h1>This is a header with # and * in the text</h1>", out);
}
test "test_with_markdown_symbols_in_the_list_item_text_that_should_not_be_interpreted" {
    const out = try m.parse(a, "* Item 1 with a # in the text\n* Item 2 with * in the text");
    defer a.free(out);
    try t.expectEqualStrings("<ul><li>Item 1 with a # in the text</li><li>Item 2 with * in the text</li></ul>", out);
}
test "test_with_markdown_symbols_in_the_paragraph_text_that_should_not_be_interpreted" {
    const out = try m.parse(a, "This is a paragraph with # and * in the text");
    defer a.free(out);
    try t.expectEqualStrings("<p>This is a paragraph with # and * in the text</p>", out);
}
test "test_unordered_lists_close_properly_with_preceding_and_following_lines" {
    const out = try m.parse(a, "# Start a list\n* Item 1\n* Item 2\nEnd a list");
    defer a.free(out);
    try t.expectEqualStrings("<h1>Start a list</h1><ul><li>Item 1</li><li>Item 2</li></ul><p>End a list</p>", out);
}
